def _format_message_from_error(self, error: Dict) -> str:
    """Format message from the error field.

    Args:
        The error field.

    Returns:
        A formatted error message.

    Raises:
        IBMQJobApiError: If invalid data received from the server.
    """
    try:
        return "{}. Error code: {}.".format(error['message'], error['code'])
    except KeyError as ex:
        raise IBMQJobApiError('Failed to get error message for job {}. Invalid error '
                              'data received: {}'.format(self.job_id(), error)) from ex

def _parse_time_per_step(self, time_per_step: Optional[Dict]) -> Optional[Dict]:
    """Parse time per step values from strings to datetime objects.

    Args:
        time_per_step: Dictionary of time per step with string values.

    Returns:
        Dictionary with datetime values or None if input is None.
    """
    if time_per_step is None:
        return None

    parsed_time_per_step = {}
    for step_name, time_data in time_per_step.items():
        if time_data is not None:
            parsed_time_per_step[step_name] = dateutil.parser.isoparse(time_data)
        else:
            parsed_time_per_step[step_name] = None
    return parsed_time_per_step

