        elif opname == "C(PSWAP)":
            self._state.mcu(device_wires.labels[:-1], device_wires.labels[-1], 0, 0, par[0])
            self._state.cswap(
                device_wires.labels[:-2],
                device_wires.labels[-2],
                device_wires.labels[-1],
